package studio.folio.resume;
import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.List;
@RestController @RequestMapping("/api/resumes") public class ResumeController {private final ResumeRepository resumes;public ResumeController(ResumeRepository resumes){this.resumes=resumes;}private ResumeDocument owned(String id,String owner){return resumes.findById(id).filter(r->owner.equals(r.ownerId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resume not found"));}@GetMapping public List<ResumeDocument> list(java.security.Principal p){return resumes.findAllByOwnerIdOrderByUpdatedAtDesc(p.getName());}@PostMapping public ResumeDocument create(@RequestBody ResumeDocument r,java.security.Principal p){r.id=null;r.ownerId=p.getName();r.createdAt=Instant.now();r.updatedAt=r.createdAt;return resumes.save(r);}@GetMapping("/{id}") public ResumeDocument get(@PathVariable String id,java.security.Principal p){return owned(id,p.getName());}@PutMapping("/{id}") public ResumeDocument update(@PathVariable String id,@RequestBody ResumeDocument body,java.security.Principal p){ResumeDocument r=owned(id,p.getName());r.title=body.title;r.theme=body.theme;r.accent=body.accent;r.data=body.data;r.updatedAt=Instant.now();return resumes.save(r);}@DeleteMapping("/{id}") public void delete(@PathVariable String id,java.security.Principal p){resumes.delete(owned(id,p.getName()));}}

